// Channel direcional em assinatura (melhora API)
func producer(out chan<- int) { out <- 1 }
func consumer(in <-chan int)  { v := <-in; _ = v }

func fetchWithTimeout(ctx context.Context, url string) (string, error) {
    result := make(chan string, 1)
    errCh  := make(chan error, 1)

    go func() {
        body, err := doFetch(url)
        if err != nil {
            errCh <- err
            return
        }
        result <- body
    }()

    select {
    case body := <-result:
        return body, nil
    case err := <-errCh:
        return "", err
    case <-ctx.Done():
        return "", ctx.Err()
    }
}

func fanOutFanIn(urls []string) []Result {
    jobs    := make(chan string, len(urls))
    results := make(chan Result, len(urls))

    const workers = 8
    var wg sync.WaitGroup
    for i := 0; i < workers; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for u := range jobs {
                results <- fetch(u)
            }
        }()
    }
    for _, u := range urls { jobs <- u }
    close(jobs)

    go func() { wg.Wait(); close(results) }()

    out := make([]Result, 0, len(urls))
    for r := range results { out = append(out, r) }
    return out
}
